// Locale-aware formatting for a French/English product in Cameroon. Generated by `eos scaffold i18n`;
// yours to edit. Uses only the built-in Intl APIs (no library bytes). Ref: .eos/packs/ref/frontend/i18n-l10n.md
// XAF has no minor unit (ISO 4217 exponent 0): pass integer francs, never computed floats.
// Times are stored in UTC and shown in Africa/Douala (UTC+1, no daylight saving); always pass the zone so
// server-rendered and browser-rendered text match.

export type AppLocale = "fr" | "en";
export const TIME_ZONE = "Africa/Douala";
const INTL_LOCALE: Record<AppLocale, string> = { fr: "fr-CM", en: "en-CM" };

export function formatXaf(francs: number, locale: AppLocale): string {
  if (!Number.isInteger(francs)) throw new RangeError(`XAF amounts are whole francs, got ${francs}`);
  return new Intl.NumberFormat(INTL_LOCALE[locale], { style: "currency", currency: "XAF" }).format(francs);
}

export function formatDateTime(date: Date, locale: AppLocale): string {
  return new Intl.DateTimeFormat(INTL_LOCALE[locale], {
    dateStyle: "long",
    timeStyle: "short",
    timeZone: TIME_ZONE,
  }).format(date);
}

export function formatDate(date: Date, locale: AppLocale): string {
  return new Intl.DateTimeFormat(INTL_LOCALE[locale], { dateStyle: "medium", timeZone: TIME_ZONE }).format(date);
}

// Parse what a user typed in an amount field: "1 234 567", "1,234,567", "1.234.567 FCFA" -> 1234567.
// Separators are accepted only between groups of three digits, so "12.5" or "1,5" (decimals, which XAF
// does not have) are rejected instead of silently becoming 125 or 15. Returns null when not valid.
export function parseXafInput(raw: string): number | null {
  const s = raw.replace(/fcfa|xaf/gi, "").trim();
  if (!/^(\d{1,15}|\d{1,3}([ \u00a0\u202f.,']\d{3}){1,4})$/.test(s)) return null;
  return Number(s.replace(/\D/g, ""));
}
